#!/usr/bin/env python3
"""Write a small invented Java serialization stream from the public stream grammar."""
from pathlib import Path
import struct

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / "synthetic" / "javaser"

def utf(text: str) -> bytes:
    raw = text.encode("utf-8")
    return struct.pack(">H", len(raw)) + raw

def string(text: str) -> bytes:
    raw = text.encode("utf-8")
    if len(raw) <= 65535:
        return b"\x74" + struct.pack(">H", len(raw)) + raw
    return b"\x7c" + struct.pack(">Q", len(raw)) + raw

def save_stream() -> bytes:
    # OpenJDK ObjectOutputStream output for the invented classes in target/javaser/.
    return bytes.fromhex("""
        
    """)

def reset_and_long_string() -> bytes:
    return (b"\xac\xed\x00\x05" + string("first") + b"\x79" +
            string("x" * 65536))

def main() -> None:
    OUT.mkdir(parents=True, exist_ok=True)
    (OUT / "save-data.ser").write_bytes(save_stream())
    (OUT / "reset-long-string.ser").write_bytes(reset_and_long_string())

if __name__ == "__main__":
    main()
